"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["53956"],{80527(e){e.exports=JSON.parse('{"id":"F144","slug":"goodwill-impairment-test","name":"Goodwill Impairment Test","subject":"Financial Statement Analysis","section":"Quality & Red Flags","topic":"Goodwill and impairments","level":"Intermediate","aliases":["impairment loss","recoverable amount","cash generating unit","carrying amount"],"formula":{"latex":"\\\\text{Recoverable}=\\\\max(FVLCD,VIU),\\\\quad \\\\text{Impairment}=\\\\max(\\\\text{Carrying}-\\\\text{Recoverable},0)","also":[],"text":"Recoverable amount = higher of (Fair value less costs of disposal) and (Value in use); Impairment loss = Carrying amount - Recoverable amount, if positive; it first reduces goodwill"},"symbols":[{"symbol":"Carrying amount","meaning":"Book value of the unit\'s assets, including goodwill","unit":"money"},{"symbol":"FVLCD","meaning":"Fair value less costs of disposal, what the unit would fetch if sold","unit":"money"},{"symbol":"VIU","meaning":"Value in use, the present value of cash flows from keeping it","unit":"money"},{"symbol":"Goodwill","meaning":"Goodwill allocated to the unit","unit":"money"}],"when_to_use":"Use it to see how an impairment loss arises. Goodwill is not amortized under IFRS or US GAAP for most firms, so it is tested at least yearly. If the unit\'s value falls below its book value, the difference is written off, first against goodwill. A sudden impairment often signals that an acquisition was overpriced.","worked_example":{"problem":"A business unit has a carrying amount of 500 including goodwill of 120. Its fair value less costs of disposal is 430 and its value in use is 410.","inputs":{"carry":500,"gw":120,"fv":430,"viu":410},"steps":[{"label":"Recoverable amount = higher of the two","working":"max(430, 410)","value":"430.00"},{"label":"Impairment = carrying - recoverable (if positive)","working":"max(500-430, 0)","value":"70.00"},{"label":"Charged to goodwill first","working":"min(70, 120)","value":"70.00"},{"label":"Goodwill remaining","working":"120-70","value":"50.00"},{"label":"Charged to other assets","working":"70-70","value":"0.00"}],"answer":"The recoverable amount is 430.00, the higher of the two. The impairment is 70.00. Goodwill absorbs it first, so 70.00 is written off goodwill, leaving goodwill of 50.00 and 0.00 to be spread over other assets."},"calculator":{"available":true,"inputs":[{"id":"carry","label":"Carrying amount","unit":"money","type":"number","default":500,"hint":""},{"id":"gw","label":"Goodwill in the unit","unit":"money","type":"number","default":120,"hint":""},{"id":"fv","label":"Fair value less costs of disposal","unit":"money","type":"number","default":430,"hint":""},{"id":"viu","label":"Value in use","unit":"money","type":"number","default":410,"hint":""}],"checks":[],"steps":[{"id":"rec","label":"Recoverable amount = higher of the two","expr":"max(fv, viu)","format":"money"},{"id":"imp","label":"Impairment = carrying - recoverable (if positive)","expr":"max(carry-rec, 0)","format":"money"},{"id":"gw_hit","label":"Charged to goodwill first","expr":"min(imp, gw)","format":"money"},{"id":"gw_left","label":"Goodwill remaining","expr":"gw-gw_hit","format":"money"},{"id":"other","label":"Charged to other assets","expr":"imp-gw_hit","format":"money"}],"results":["imp","gw_left"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"rec":430,"imp":70,"gw_hit":70,"gw_left":50,"other":0}},"finder":{"finds":"The write-down when a unit is worth less than its book value","needs":"Carrying amount, goodwill, fair value, value in use"},"related":[{"slug":"purchase-price-allocation-goodwill","name":"Goodwill from Purchase Price Allocation"},{"slug":"acquisition-npv","name":"Value Created by an Acquisition"}],"related_ids":["F218","F199"],"group":"Companies and valuation","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mtext>Recoverable</mtext><mo>=</mo><mi>max</mi><mo>\u2061</mo><mo stretchy=\\"false\\">(</mo><mi>F</mi><mi>V</mi><mi>L</mi><mi>C</mi><mi>D</mi><mo separator=\\"true\\">,</mo><mi>V</mi><mi>I</mi><mi>U</mi><mo stretchy=\\"false\\">)</mo><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mtext>Impairment</mtext><mo>=</mo><mi>max</mi><mo>\u2061</mo><mo stretchy=\\"false\\">(</mo><mtext>Carrying</mtext><mo>\u2212</mo><mtext>Recoverable</mtext><mo separator=\\"true\\">,</mo><mn>0</mn><mo stretchy=\\"false\\">)</mo></mrow><annotation encoding=\\"application/x-tex\\">\\\\text{Recoverable}=\\\\max(FVLCD,VIU),\\\\quad \\\\text{Impairment}=\\\\max(\\\\text{Carrying}-\\\\text{Recoverable},0)</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"purchase-price-allocation-goodwill","name":"Goodwill from Purchase Price Allocation"},"next":{"slug":"debt-dynamics","name":"Government Debt Dynamics"},"lesson":null,"total":522}')}}]);